using System;using System.IO;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using Staff.Subway;
public static class ContinuousSolarSetup {
 [MenuItem("STAFF/Subway/Enable Continuous Solar Day")]
 public static void Install(){if(EditorApplication.isPlaying)throw new Exception("Exit Play mode first.");var sky=UnityEngine.Object.FindFirstObjectByType<SubwayTimeOfDay>();if(!sky)throw new Exception("Open subway scene.");Directory.CreateDirectory("Library/StaffSubway");EditorSceneManager.SaveScene(sky.gameObject.scene,"Library/StaffSubway/before-continuous-day.unity",true);Undo.RecordObjects(new UnityEngine.Object[]{sky,sky.atmosphere},"Continuous solar day");sky.continuousSolarLighting=true;sky.skyWeather.cloudMotionMultiplier=3;sky.skyWeather.starRevolutionSeconds=1200;sky.skyWeather.animate=true;sky.atmosphere.useDayCycle=true;sky.atmosphere.animate=true;sky.ApplySolarDay();sky.ApplySky();EditorUtility.SetDirty(sky);EditorUtility.SetDirty(sky.atmosphere);EditorSceneManager.MarkSceneDirty(sky.gameObject.scene);EditorSceneManager.SaveScene(sky.gameObject.scene);Debug.Log("Continuous Solar Day saved; cloud motion 3x; star revolution 1200 seconds.");}
}
